p='src/types/checker/inference/expr/effects.rs'
s=open(p).read()
old = """    /// Only a CHANGE in element representation is written. Assigning the parameter type
    /// unconditionally would let a callee compiled for `array<int>` NARROW a caller that holds
    /// `array<mixed>` — the same defect in reverse, and one no call site can justify: a callee
    /// cannot unbox storage it does not own."""
new = """    /// Only a WIDENING is written. Assigning the parameter type unconditionally would let a
    /// callee compiled for `array<int>` NARROW a caller that holds `array<mixed>` — the same
    /// defect in reverse, and one no call site can justify: a callee cannot unbox storage it
    /// does not own."""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('doc corrected')
